<script lang="ts">import {onMount,getContext} from 'svelte';import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';import {createPurchaseOrdersState} from '../state/purchaseOrdersState.svelte';import type {CreatePurchaseOrder} from '../../domain/entity/PurchaseOrder';const i18n=getContext<I18nState>('i18n');const selection=getContext<{warehouseId:number|null}>('warehouseSelection');const vm=createPurchaseOrdersState();let open=$state(false),poNumber=$state(''),vendorName=$state(''),expectedDate=$state(''),notes=$state(''),itemId=$state(''),quantity=$state('1'),unitCost=$state('');onMount(()=>{void vm.load(selection?.warehouseId??null);});async function create(){const payload:CreatePurchaseOrder={poNumber,warehouseId:selection?.warehouseId??0,vendorName,expectedDate:expectedDate||null,notes:notes||null,lines:[{itemId:Number(itemId),quantityOrdered:Number(quantity),unitCost:unitCost?Number(unitCost):null}]};if(await vm.create(payload)){open=false;poNumber='';vendorName='';expectedDate='';notes='';itemId='';quantity='1';unitCost='';await vm.load(selection?.warehouseId??null);}}async function toggle(id:number,status:string){if(await vm.lifecycle(id,status==='CLOSED'?'reopen':'close'))await vm.load(selection?.warehouseId??null);}</script>
<section class="page"><header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Órdenes de compra')}</h1><p>{i18n.t('Consulta órdenes, crea pedidos de compra y administra su ciclo de cierre.')}</p></div><button class="primary" onclick={()=>open=!open}>{i18n.t('Nueva orden')}</button></header>
{#if vm.error}<p class="error" role="alert">{vm.error}</p>{/if}
{#if open}<form class="editor" onsubmit={e=>{e.preventDefault();void create();}}><h2>{i18n.t('Crear orden de compra')}</h2><label>{i18n.t('Número de orden')}<input required bind:value={poNumber}/></label><label>{i18n.t('Proveedor')}<input bind:value={vendorName}/></label><label>{i18n.t('Fecha prevista')}<input type="date" bind:value={expectedDate}/></label><label>{i18n.t('ID de producto')}<input type="number" min="1" required bind:value={itemId}/></label><label>{i18n.t('Cantidad')}<input type="number" min="1" required bind:value={quantity}/></label><label>{i18n.t('Costo unitario')}<input type="number" min="0" step="0.01" bind:value={unitCost}/></label><label class="wide">{i18n.t('Notas')}<input bind:value={notes}/></label><div class="actions"><button type="button" onclick={()=>open=false}>{i18n.t('Cancelar')}</button><button class="primary" disabled={vm.saving||!selection?.warehouseId}>{i18n.t('Guardar')}</button></div></form>{/if}
<div class="toolbar"><input placeholder={i18n.t('Buscar por número o proveedor')} value={vm.search} oninput={e=>vm.setSearch(e.currentTarget.value)} onkeydown={e=>{if(e.key==='Enter')void vm.load(selection?.warehouseId??null);}}/><select value={vm.status} onchange={e=>{vm.setStatus(e.currentTarget.value);void vm.load(selection?.warehouseId??null);}}><option value="">{i18n.t('Todos los estados')}</option>{#each ['OPEN','PARTIAL','RECEIVED','CLOSED','ARCHIVED'] as s}<option value={s}>{s}</option>{/each}</select><button onclick={()=>void vm.load(selection?.warehouseId??null)}>{i18n.t('Buscar')}</button></div>
{#if vm.loading}<p>{i18n.t('Cargando…')}</p>{:else}<div class="table-wrap"><table><thead><tr><th>{i18n.t('Orden')}</th><th>{i18n.t('Proveedor')}</th><th>{i18n.t('Almacén')}</th><th>{i18n.t('Estado')}</th><th>{i18n.t('Fecha prevista')}</th><th>{i18n.t('Acciones')}</th></tr></thead><tbody>{#each vm.rows as r (r.poId)}<tr><td><button class="link" onclick={()=>void vm.detail(r.poId)}>{r.poNumber}</button></td><td>{r.vendorName??'—'}</td><td>{r.warehouseId}</td><td>{r.status}</td><td>{r.expectedDate??'—'}</td><td>{#if r.status==='CLOSED'}<button onclick={()=>void toggle(r.poId,r.status)}>{i18n.t('Reabrir')}</button>{:else if r.status!=='ARCHIVED'}<button onclick={()=>void toggle(r.poId,r.status)}>{i18n.t('Cerrar')}</button>{/if}</td></tr>{/each}</tbody></table></div>{/if}
{#if vm.selected}<aside class="detail"><button onclick={()=>vm.clearSelected()}>{i18n.t('Cerrar detalle')}</button><h2>{vm.selected.poNumber}</h2><p>{vm.selected.vendorName} · {vm.selected.status}</p><table><thead><tr><th>SKU</th><th>{i18n.t('Producto')}</th><th>{i18n.t('Solicitado')}</th><th>{i18n.t('Recibido')}</th><th>{i18n.t('Estado')}</th></tr></thead><tbody>{#each vm.selected.lines as l (l.poLineId)}<tr><td>{l.sku??'—'}</td><td>{l.itemName??l.itemId}</td><td>{l.quantityOrdered}</td><td>{l.quantityReceived}</td><td>{l.status}</td></tr>{/each}</tbody></table></aside>{/if}</section>
<style>.page{max-width:78rem;margin:1.4rem auto;padding:0 1.1rem;color:var(--ink)}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1rem}h1{margin:0;font:700 1.6rem var(--disp)}header p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em}button{border:1px solid var(--line);border-radius:8px;padding:.55rem .8rem;background:var(--card);color:var(--ink);cursor:pointer}.primary{background:var(--navy);color:white;border-color:var(--navy)}.editor{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.7rem;padding:1rem;border:1px solid var(--line);border-radius:12px;background:var(--card)}.editor h2,.wide,.actions{grid-column:1/-1}.editor label{display:grid;gap:.3rem;color:var(--slate);font-size:.8rem}.editor input,.toolbar input,.toolbar select{min-height:39px;border:1px solid var(--line);border-radius:8px;padding:.5rem .65rem;background:var(--card);color:var(--ink)}.actions{display:flex;justify-content:flex-end;gap:.5rem}.toolbar{display:flex;gap:.5rem;margin:1rem 0}.toolbar input{flex:1}.table-wrap,.detail{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card);margin:1rem 0}.detail{padding:1rem}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.84rem}th,td{text-align:left;padding:.7rem;border-bottom:1px solid var(--line)}th{color:var(--slate);font-size:.72rem;text-transform:uppercase}.link{border:0;background:none;color:var(--accent);text-decoration:underline}.error{color:var(--danger)}@media(max-width:640px){header{align-items:flex-start;flex-direction:column}.editor{grid-template-columns:1fr}.toolbar{flex-wrap:wrap}}</style>